// Runs in the browser — gives the user instant feedback
function validateAge(input) {
  const age = Number(input.value);
  if (age < 18) {
    showError('You must be 18 or older.');
    return false;
  }
  return true;
}

// A user could open DevTools and simply call the
// underlying submit function directly, skipping
// validateAge() entirely. That's why the SAME rule
// (age >= 18) must also be enforced on the server
// before the server actually saves anything.

