import React from 'react';

export default function ConsoleDemo() {
  const handleLog = () => console.log('Order submitted:', { id: 42, total: 19.99 });
  const handleWarn = () => console.warn('Cart total exceeds free-shipping threshold check skipped');
  const handleError = () => console.error('Failed to save order: network request timed out');

  return (
    <div style={{ padding: 16, background: '#0d1117', fontFamily: 'sans-serif', display: 'flex', gap: 8 }}>
      <button onClick={handleLog} style={{ background: '#238636', color: '#fff', border: 'none', padding: '8px 12px', borderRadius: 6, cursor: 'pointer' }}>
        console.log
      </button>
      <button onClick={handleWarn} style={{ background: '#9e6a03', color: '#fff', border: 'none', padding: '8px 12px', borderRadius: 6, cursor: 'pointer' }}>
        console.warn
      </button>
      <button onClick={handleError} style={{ background: '#da3633', color: '#fff', border: 'none', padding: '8px 12px', borderRadius: 6, cursor: 'pointer' }}>
        console.error
      </button>
    </div>
  );
}

import React, { useState } from 'react';

export default function NetworkDemo() {
  const [result, setResult] = useState('Click the button, then check the Network tab.');

  const loadData = async () => {
    setResult('Loading...');
    try {
      const response = await fetch('https://jsonplaceholder.typicode.com/todos/1');
      const data = await response.json();
      setResult(`Status ${response.status} — got: ${JSON.stringify(data)}`);
    } catch (err) {
      setResult('Request failed: ' + err.message);
    }
  };

  return (
    <div style={{ padding: 16, background: '#0d1117', color: '#e6edf3', fontFamily: 'sans-serif' }}>
      <button
        onClick={loadData}
        style={{ background: '#238636', color: '#fff', border: 'none', padding: '8px 16px', borderRadius: 6, cursor: 'pointer', marginBottom: 12 }}
      >
        Fetch a Todo
      </button>
      <pre style={{ background: '#161b22', padding: 12, borderRadius: 6, fontSize: 13, whiteSpace: 'pre-wrap' }}>
        {result}
      </pre>
    </div>
  );
}

import React, { useState } from 'react';

export default function BuggyCounter() {
  const [count, setCount] = useState(0);

  const handleClick = () => {
    setCount(count + 1);
    // Bug: this reads the OLD `count` from this render's closure,
    // not the freshly updated value — so it always logs one click
    // behind, like a friend who's perpetually one text message
    // behind in the conversation.
    console.log('Count is now:', count);
  };

  return (
    <div style={{ padding: 16, background: '#0d1117', color: '#e6edf3', fontFamily: 'sans-serif' }}>
      <p style={{ fontSize: 24 }}>{count}</p>
      <button
        onClick={handleClick}
        style={{ background: '#238636', color: '#fff', border: 'none', padding: '8px 16px', borderRadius: 6, cursor: 'pointer' }}
      >
        Click me
      </button>
    </div>
  );
}

